package solution

import (
	"reflect"
	"strings"
	"testing"
)

func TestBooleanAndNilMatchers(t *testing.T) {
	if err := Check(true, IsTrue()); err != nil {
		t.Fatalf("IsTrue rejected true: %v", err)
	}
	if err := Check(false, IsFalse()); err != nil {
		t.Fatalf("IsFalse rejected false: %v", err)
	}
	if err := Check(false, IsTrue()); err == nil || err.Error() == "" {
		t.Fatalf("IsTrue failure must contain explanation: %v", err)
	}
	if err := Check(true, IsFalse()); err == nil || err.Error() == "" {
		t.Fatalf("IsFalse failure must contain explanation: %v", err)
	}
	if err := Check(1, IsTrue()); err == nil {
		t.Fatal("IsTrue accepted a non-bool value")
	}

	var pointer *int
	var slice []byte
	var mapping map[string]int
	var channel chan int
	var function func()
	for _, value := range []any{nil, pointer, slice, mapping, channel, function} {
		if err := Check(value, IsNil()); err != nil {
			t.Errorf("IsNil rejected %#v: %v", value, err)
		}
	}
	zero := 0
	for _, value := range []any{zero, "", []byte{}, &zero} {
		if err := Check(value, IsNil()); err == nil {
			t.Errorf("IsNil accepted non-nil %#v", value)
		}
	}
}

func TestEqualUsesDeepEqualityWithoutMutation(t *testing.T) {
	expected := map[string][]int{"numbers": {1, 2, 3}}
	actual := map[string][]int{"numbers": {1, 2, 3}}
	expectedBefore := map[string][]int{"numbers": {1, 2, 3}}
	actualBefore := map[string][]int{"numbers": {1, 2, 3}}
	matcher := Equal(expected)
	if err := Check(actual, matcher); err != nil {
		t.Fatalf("Equal rejected deeply equal values: %v", err)
	}
	if !reflect.DeepEqual(expected, expectedBefore) || !reflect.DeepEqual(actual, actualBefore) {
		t.Fatal("Equal mutated expected or actual")
	}
	if err := Check(map[string][]int{"numbers": {1, 2}}, matcher); err == nil {
		t.Fatal("Equal accepted different value")
	}
}

func TestCheckMessagesNilMatcherAndNot(t *testing.T) {
	matcher := Matcher(func(actual any) (bool, string) {
		return false, "base explanation"
	})
	if err := Check(123, matcher, "context", "ignored"); err == nil || err.Error() != "context: base explanation" {
		t.Fatalf("prefixed Check error = %v", err)
	}
	if err := Check(123, matcher, "", "ignored"); err == nil || err.Error() != "base explanation" {
		t.Fatalf("empty first message handling = %v", err)
	}
	if err := Check(123, nil); err == nil {
		t.Fatal("nil matcher did not return an error")
	}

	if err := Check("x", Not(Equal("y"))); err != nil {
		t.Fatalf("Not should succeed when nested matcher fails: %v", err)
	}
	if err := Check("x", Not(Equal("x"))); err == nil || !strings.Contains(err.Error(), "unexpected match") {
		t.Fatalf("Not successful nested match error = %v", err)
	}
	ok, explanation := Not(Equal(10))(11)
	if !ok || explanation != "" {
		t.Fatalf("successful Not result = %v, %q", ok, explanation)
	}
}

