type Matcher func(actual any) (bool, string)

func Check(actual any, matcher Matcher, message ...string) error {
	if matcher == nil {
		return errors.New("nil matcher")
	}
	ok, explanation := matcher(actual)
	if ok {
		return nil
	}
	if len(message) > 0 && message[0] != "" {
		explanation = message[0] + ": " + explanation
	}
	return errors.New(explanation)
}

