	return func(actual any) (bool, string) {
		v, ok := actual.(bool)
		return ok && v, fmt.Sprintf("expected true, got %v", actual)
	}
}

func IsFalse() Matcher {
	return func(actual any) (bool, string) {
		v, ok := actual.(bool)
		return ok && !v, fmt.Sprintf("expected false, got %v", actual)
	}
}

func IsNil() Matcher {
	return func(actual any) (bool, string) {
		if actual == nil {
			return true, ""
		}
		v := reflect.ValueOf(actual)
		switch v.Kind() {
		case reflect.Chan, reflect.Func, reflect.Interface, reflect.Map, reflect.Pointer, reflect.Slice:
			if v.IsNil() { return true, "" }
		}
		return false, fmt.Sprintf("expected nil, got %v", actual)
	}
}

func Equal(expected any) Matcher {
	return func(actual any) (bool, string) {
		if reflect.DeepEqual(actual, expected) {
			return true, ""
		}
		return false, fmt.Sprintf("expected %v, got %v", expected, actual)
	}
}

func Not(m Matcher) Matcher {
	return m
}

